<div class="wrap studio-wrap"><h1>Sicurezza e tracciamento</h1><?php if(isset($_GET['logs_deleted'])):?><div class="notice notice-success is-dismissible"><p>Eliminati <?php echo (int)$_GET['logs_deleted'];?> eventi dal <?php echo esc_html($_GET['range_from']??'');?> al <?php echo esc_html($_GET['range_to']??'');?>. L’operazione è stata registrata come pulizia_log.</p></div><?php endif;?><div class="studio-panel"><h2>Elimina log per intervallo date</h2><p>L’eliminazione è definitiva. Il nuovo evento <code>pulizia_log</code> conserverà il range selezionato e il numero di record rimossi.</p><form method="post" onsubmit="return confirm('Confermi l’eliminazione definitiva dei log compresi nel range selezionato?');"><?php wp_nonce_field('studio_delete_logs');?><div class="studio-form-grid"><div class="studio-field"><label>Data iniziale</label><input type="date" name="delete_from" required></div><div class="studio-field"><label>Data finale</label><input type="date" name="delete_to" required></div></div><button type="submit" name="studio_delete_logs" class="button button-primary">Elimina log nel range</button></form></div><div class="studio-panel"><h2>Ricerca avanzata</h2><form method="get"><input type="hidden" name="page" value="studio-sicurezza"><div class="studio-form-grid"><div class="studio-field"><label>Ricerca in tutto il testo</label><input type="search" name="audit_text" value="<?php echo esc_attr($text);?>" placeholder="Azione, oggetto, dettagli, utente..."></div><div class="studio-field"><label>Utente</label><select name="audit_user"><option value="0">Tutti gli utenti</option><?php foreach($users as $u):?><option value="<?php echo (int)$u->ID;?>" <?php selected($user_id,$u->ID);?>><?php echo esc_html($u->display_name);?></option><?php endforeach;?></select></div><div class="studio-field"><label>Azione</label><select name="audit_action"><option value="">Tutte le azioni</option><?php foreach($actions as $a):?><option value="<?php echo esc_attr($a);?>" <?php selected($action,$a);?>><?php echo esc_html($a);?></option><?php endforeach;?></select></div><div class="studio-field"><label>Ultimi giorni</label><select name="audit_days"><option value="0">Qualsiasi data</option><?php foreach(array(1,7,15,30,90,180,365) as $d):?><option value="<?php echo $d;?>" <?php selected($days,$d);?>>Ultimi <?php echo $d;?> giorni</option><?php endforeach;?></select></div><div class="studio-field"><label>Dal giorno</label><input type="date" name="audit_from" value="<?php echo esc_attr($from);?>"></div><div class="studio-field"><label>Al giorno</label><input type="date" name="audit_to" value="<?php echo esc_attr($to);?>"></div></div><button class="button button-primary">Cerca</button> <a class="button" href="<?php echo esc_url(admin_url('admin.php?page=studio-sicurezza'));?>">Azzera filtri</a></form></div><div class="studio-panel"><p><strong><?php echo (int)$total;?></strong> eventi trovati. L'indirizzo IP è conservato esclusivamente come hash.</p><table class="widefat striped"><thead><tr><th>Data</th><th>Utente</th><th>Azione</th><th>Oggetto</th><th>Dettagli</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?php echo esc_html(date_i18n('d/m/Y H:i:s',strtotime($l->data_evento)));?></td><td><?php echo esc_html($l->display_name?:'Utente #'.$l->user_id);?></td><td><?php echo esc_html($l->azione);?></td><td><?php echo esc_html($l->oggetto.' #'.$l->oggetto_id);?></td><td><code><?php echo esc_html($l->dettagli);?></code></td></tr><?php endforeach;?></tbody></table><?php echo wp_kses_post(paginate_links(array('base'=>add_query_arg('paged','%#%'),'current'=>$page,'total'=>max(1,ceil($total/$per)))));?></div></div>
